export function validateLearnerState(data: unknown): boolean {
	if (data === null || typeof data !== "object") return false;
	const obj = data as Record<string, unknown>;

	if (!Array.isArray(obj.completedLessons)) return false;
	if (
		typeof obj.cards !== "object" ||
		obj.cards === null ||
		Array.isArray(obj.cards)
	)
		return false;
	if (!Array.isArray(obj.sessionHistory)) return false;

	return true;
}
===JSONSTORE===
/**
 * A minimal validating JSON blob store, mirroring `Storage.ts`'s
 * `IStorage`/`LocalStorageAdapter`/`InMemoryStorage` split. Unlike
 * `IStorage` (which always returns *some* `LearnerState`, defaulting to
 * `INITIAL_LEARNER_STATE`), `JsonStore.load()` is three-state: a store that
 * has never been written to ("empty") must stay distinguishable from one
 * whose stored value is unreadable ("corrupt") — the caller decides what
 * each means, this layer only reports which happened.
 */
export type JsonStoreLoadResult<T> =
	| { readonly status: "empty" }
	| { readonly status: "ok"; readonly value: T }
	| { readonly status: "corrupt" };

export type JsonStoreSaveResult =
	| { readonly status: "ok" }
	| { readonly status: "failed" };

/** Narrows `unknown` to `T`, used to reject a parsed-but-wrong-shape value. */
export type JsonShapeGuard<T> = (value: unknown) => value is T;

export interface JsonStore<T> {
	load(): JsonStoreLoadResult<T>;
	save(value: T): JsonStoreSaveResult;
}

/**
 * Backed by `localStorage` under a caller-supplied `key`. Never throws:
 * invalid JSON, a value failing `isValidShape`, `localStorage` being
 * unavailable, or `setItem` throwing (e.g. `QuotaExceededError`) are all
 * surfaced as typed results.
 */
export class LocalStorageJsonStore<T> implements JsonStore<T> {
	constructor(
		private readonly key: string,
		private readonly isValidShape: JsonShapeGuard<T>,
	) {}

	load(): JsonStoreLoadResult<T> {
		if (typeof localStorage === "undefined") return { status: "empty" };
		const raw = localStorage.getItem(this.key);
		if (raw === null) return { status: "empty" };

		let parsed: unknown;
		try {
			parsed = JSON.parse(raw);
		} catch {
			return { status: "corrupt" };
		}

		if (!this.isValidShape(parsed)) return { status: "corrupt" };
		return { status: "ok", value: parsed };
	}

	save(value: T): JsonStoreSaveResult {
		if (typeof localStorage === "undefined") return { status: "ok" };
		try {
			localStorage.setItem(this.key, JSON.stringify(value));
			return { status: "ok" };
		} catch {
			return { status: "failed" };
		}
	}
}

/** In-memory equivalent, for tests and non-browser callers. */
export class InMemoryJsonStore<T> implements JsonStore<T> {
	private value: T | undefined;

	load(): JsonStoreLoadResult<T> {
		return this.value === undefined
			? { status: "empty" }
			: { status: "ok", value: this.value };
	}

	save(value: T): JsonStoreSaveResult {
		this.value = value;
		return { status: "ok" };
	}
}
===STORAGE 80-180===

export class LocalStorageAdapter implements IStorage {
	private readonly key: string;

	/**
	 * The parsed state, memoized against the exact raw string it came from.
	 *
	 * Without it every repository method re-ran `JSON.parse` + `migrateState`
	 * over the whole learner state. Because pages call use cases directly
	 * from their render bodies, one Dashboard render did that 42 times —
	 * ~12 MB of JSON parsed for a single render, and ~5 MB more on every
	 * answered card via the `Layout` shell's re-render. That was the app's
	 * dominant CPU cost on a phone.
	 *
	 * `getItem` is still called every time and the result compared, so a
	 * write that bypasses this adapter (another tab, a test seeding the key
	 * directly, devtools) is still picked up exactly as before — the cache
	 * changes how fast a load is, never what it observes.
	 *
	 * The cached object is returned **live, not cloned**: cloning costs more
	 * than the parse it replaces (measured: `structuredClone` 0.79 ms vs
	 * `JSON.parse` 0.57 ms on a 282 KB state). That is sound because every
	 * caller here either only reads, or follows the load-mutate-save shape
	 * the repositories use, where mutating then saving is the intended
	 * effect. Note this differs from `InMemoryStorage`, which clones on both
	 * ends.
	 */
	private cache: LearnerState | null = null;
	/** The exact `getItem` string `cache` was parsed from. */
	private cacheRaw: string | null = null;

	constructor(key = "thai-srs-state") {
		this.key = key;
	}

	load(): LearnerState {
		if (typeof localStorage === "undefined") {
			return structuredClone(INITIAL_LEARNER_STATE);
		}
		const raw = localStorage.getItem(this.key);
		if (raw !== null && raw === this.cacheRaw && this.cache) {
			return this.cache;
		}
		if (!raw) {
			this.cache = null;
			this.cacheRaw = null;
			return structuredClone(INITIAL_LEARNER_STATE);
		}
		const state = JSON.parse(raw) as LearnerState;
		if (!state.vocabCards) {
			state.vocabCards = {};
		}
		if (!state.grammarCards) {
			state.grammarCards = {};
		}
		if (!state.sentenceCards) {
			state.sentenceCards = {};
		}
		if (!state.achievements) {
			state.achievements = [];
		}
		this.cache = migrateState(state);
		this.cacheRaw = raw;
		return this.cache;
	}

	save(state: LearnerState): void {
		const raw = JSON.stringify(state);
		// Adopt what was just saved as the cache, keyed on the very string
		// written, so the next `load` is a string compare rather than a parse.
		this.cache = state;
		this.cacheRaw = raw;
		if (typeof localStorage === "undefined") return;
		localStorage.setItem(this.key, raw);
	}

